window.futvizVista("eficiencia-definicion","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"eficiencia-definicion\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"eficiencia-definicion\"]={\"id\":\"eficiencia-definicion\",\"titulo\":\"Goles vs. xG del equipo\",\"bajada\":\"A la derecha, m\u00e1s xG por partido; arriba, m\u00e1s goles. Sobre la diagonal el equipo marc\u00f3 m\u00e1s de lo que val\u00edan sus ocasiones.\",\"pregunta\":\"\u00bfQu\u00e9 equipo aprovecha mejor sus ocasiones?\",\"tabla\":\"equipos\",\"entidad\":\"equipos\",\"x\":{\"col\":\"xg_fav\",\"label\":\"xG a favor por partido (sin penales)\",\"corto\":\"xG\",\"dec\":2},\"y\":{\"col\":\"gol_fav\",\"label\":\"Goles por partido (sin penales)\",\"corto\":\"Goles\",\"dec\":2},\"referencia\":{\"tipo\":\"diagonal\",\"dif\":\"goles \u2212 xG\",\"sobre\":\"Marcan m\u00e1s de lo esperado\",\"bajo\":\"Marcan menos de lo esperado\",\"decDif\":2},\"requiere\":[\"xg_fav\",\"gol_fav\"],\"subtitulo\":\"Equipos de las 5 ligas \u00b7 {temporada} \u00b7 por partido, sin penales\",\"filtros\":{\"nivel\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"xG\",\"ayuda\":\"Ordenados por xG a favor por partido (sin penales)\"},{\"id\":\"y\",\"etiqueta\":\"Goles\",\"ayuda\":\"Ordenados por Goles por partido (sin penales)\"}],\"queMirar\":\"F\u00edjate en la distancia a la diagonal, no en la altura: un equipo puede estar arriba solo porque crea mucho. Casi todos quedan debajo porque el xG de Understat suma m\u00e1s de lo que entra, y lo que se sale en una temporada suele ser azar.\",\"insight\":\"definicion\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\"]};</script>");